steps.summary:
**Bash** D=../plugin/dev-team/scripts/dt.py; git log --oneline -3; git status --short; python3 $D status --skill api-probe | grep -E "mode|probe|leak"; python3 $D probes --scan | tail -1; for p in probes/PB-0*/evidence/results.json; do python3 -c "
import json,sys;d=json.load(open(sys.argv[1]))
print(sys.argv[1].split('/')[1],d['script_hash'],d['run_at'],d['base_url'],'ERROR:',d.get('error'))" $p; done; git diff HEAD~1 --stat | tail -3

